import { useEffect, useState } from 'react';
import transform from '@diplodoc/transform';
import { YfmStaticView } from '@gravity-ui/markdown-editor';
import '@diplodoc/transform/dist/css/yfm.css';

type Props = {
    getValue: () => string;
};

/** Превью markdown для split-режима редактора. HTML в исходнике запрещён и санитизируется. */
export function MarkdownPreview({ getValue }: Props) {
    const [html, setHtml] = useState('');
    const markup = getValue();

    useEffect(() => {
        // Небольшой debounce, чтобы не перерисовывать превью на каждое нажатие клавиши
        const timer = setTimeout(() => {
            const { result } = transform(markup, {
                allowHTML: false,
                needToSanitizeHtml: true,
                breaks: true,
                linkify: true,
            });
            setHtml(result.html);
