import { test, expect } from 'vitest';
import { createRoot } from 'react-dom/client';
import { act } from 'react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { MarkdownField } from '../components/MarkdownField';
import { renderMarkdown } from '../components/MarkdownPreview';
import type { MarkdownEditorInstance } from '@gravity-ui/markdown-editor';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;

test('renderMarkdown sanitizes and formats', () => {
  const html = renderMarkdown('# T\n**b** _i_\n<script>alert(1)</script>\n- a');
  console.log(html);
  expect(html).toContain('<strong>b</strong>');
  expect(html).not.toContain('<script>');
});

test('wysiwyg shows formatting, getValue/insert/onChange work', async () => {
  const el = document.createElement('div'); document.body.append(el);
  const ref = { current: null as MarkdownEditorInstance | null };
  const changes: string[] = [];
  await act(async () => {
    createRoot(el).render(<ThemeProvider theme="light"><MarkdownField label="Описание" initialValue={'# Заголовок\n\nТекст **жирный** и _курсив_\n\n- пункт'} editorRef={ref} onChange={(v) => changes.push(v)} /></ThemeProvider>);
  });
  await act(async () => { await new Promise(r => setTimeout(r, 100)); });
  const pm = el.querySelector('.ProseMirror')!;
  console.log(pm.innerHTML);
  expect(pm.querySelector('h1')?.textContent).toBe('Заголовок');
  expect(pm.querySelector('strong')?.textContent).toBe('жирный');
  expect(pm.querySelector('em')?.textContent).toBe('курсив');
  expect(pm.querySelector('li')).toBeTruthy();
  await act(async () => { ref.current!.moveCursor('end'); ref.current!.insert('\n\n**новый**'); await new Promise(r => setTimeout(r, 50)); });
  console.log('VALUE:', JSON.stringify(ref.current!.getValue()), 'changes:', changes.length);
  await act(async () => { ref.current!.setEditorMode('markup'); await new Promise(r => setTimeout(r, 400)); });
  console.log('MARKUP MODE HTML has preview:', !!el.querySelector('.yfm'), el.querySelector('.yfm')?.innerHTML.slice(0, 300));
  await act(async () => { ref.current!.clear(); });
  console.log('AFTER CLEAR:', JSON.stringify(ref.current!.getValue()));
});
EOF
