import { test, expect } from 'vitest';
import { createRoot } from 'react-dom/client';
import { act } from 'react';
import { ThemeProvider, Toaster, ToasterProvider } from '@gravity-ui/uikit';
import { MarkdownField } from '../components/MarkdownField';
import { App } from '../App';
import type { MarkdownEditorInstance } from '@gravity-ui/markdown-editor';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
const wait = (ms: number) => act(async () => { await new Promise(r => setTimeout(r, ms)); });

test('field: wysiwyg formatting, insert, markup preview, clear', async () => {
  const el = document.createElement('div'); document.body.append(el);
  const ref = { current: null as MarkdownEditorInstance | null };
  const changes: string[] = [];
  await act(async () => {
    createRoot(el).render(<ThemeProvider theme="light"><ToasterProvider toaster={new Toaster()}><MarkdownField label="Описание" initialValue={'# Заголовок\n\nТекст **жирный** и _курсив_\n\n- пункт'} editorRef={ref} onChange={(v) => changes.push(v)} /></ToasterProvider></ThemeProvider>);
  });
  await wait(100);
  const pm = el.querySelector('.ProseMirror')!;
  expect(pm.querySelector('h1')?.textContent).toBe('Заголовок');
  expect(pm.querySelector('strong')?.textContent).toBe('жирный');
  expect(pm.querySelector('em')?.textContent).toBe('курсив');
  expect(pm.querySelector('li')).toBeTruthy();
  console.log('TOOLBAR buttons:', el.querySelectorAll('button').length);
  await act(async () => { ref.current!.moveCursor('end'); ref.current!.insert('**новый**'); });
  await wait(50);
  console.log('VALUE:', JSON.stringify(ref.current!.getValue()), '| onChange calls:', changes.length, JSON.stringify(changes.at(-1)));
  await act(async () => { ref.current!.setEditorMode('markup'); });
  await wait(500);
  console.log('MARKUP: cm present:', !!el.querySelector('.cm-editor'), '| preview:', el.querySelector('.yfm')?.innerHTML.replace(/\s+/g,' ').slice(0, 250));
  await act(async () => { ref.current!.clear(); });
  console.log('AFTER CLEAR:', JSON.stringify(ref.current!.getValue()));
});

test('app renders with validation', async () => {
  const el = document.createElement('div'); document.body.append(el);
  await act(async () => { createRoot(el).render(<ThemeProvider theme="light"><App /></ThemeProvider>); });
  await wait(100);
  expect(el.querySelector('.ProseMirror')).toBeTruthy();
  await act(async () => { (el.querySelector('button[type=submit]') as HTMLButtonElement).click(); });
  console.log('ERRORS SHOWN:', el.textContent!.includes('Введите заголовок'), el.textContent!.includes('Введите описание'));
});
EOF
